window.AUTH=window.AUTH||{};window.AUTH["22-800"]={"d":"22-800","id":"2023/22-800","n":"Moore v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioners Charles G. Moore, et ux.","date":"2023-08-30","url":"https://www.supremecourt.gov/DocketPDF/22/22-800/278464/20230830102536217_22-800%20Brief%20for%20Petitioners.pdf","side":"pet","n":86},{"k":"respondent","label":"Brief of respondent United States","date":"2023-10-16","url":"https://www.supremecourt.gov/DocketPDF/22/22-800/285200/20231016195041390_22-800bsUnited%20States.pdf","side":"res","n":109},{"k":"reply","label":"Reply of petitioners Charles G. Moore, et ux.","date":"2023-11-15","url":"https://www.supremecourt.gov/DocketPDF/22/22-800/289622/20231115114606125_22-800%20Reply%20Brief.pdf","side":"pet","n":32}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/602us1r41_h3dj.pdf","tr":true,"items":[{"t":"case","label":"Barclay & Co. v. Edwards","cite":"267 U.S. 442","y":1925,"id":"scdb/1924-025","sc":1,"by":{"0":"51","1":"28"}},{"t":"case","label":"Bromley v. McCaughn","cite":"280 U.S. 124","y":1929,"id":"scdb/1929-012","sc":1,"by":{"0":"52"}},{"t":"case","label":"Brushaber v. Union Pac. R.R. Co.","cite":"240 U.S. 1","y":1916,"id":"scdb/1915-067","sc":1,"by":{"0":"8, 18, 19, 34, 35","1":"3, 18, 35","2":"6, 15"},"q":[{"src":"brief","b":1,"text":"embraces every conceivable power of taxation.","cite":"240 U.S. 1, 12"},{"src":"brief","b":1,"text":"‘[t]he rule of apportionment as to direct taxes.’","cite":"240 U.S. at 13"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"to lay and collect income taxes.","cite":"240 U. S., at 12"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"under the head of excises, duties and imposts.","cite":"240 U. S., at 15"},{"src":"opinion","who":"Justice Thomas, dissenting","text":"is exhaustive and embraces every conceivable power of taxation.","cite":"240 U. S. 1, 12"},{"src":"argument","who":"Mr. Grossman","text":"Subsequently, in Brushaber, the Court recognized that at the time, that wasn't really considered or thought about as being much of a defect with respect to the direct tax clauses under sort of the reasoning of Springer."}]},{"t":"case","label":"Burk-Waggoner Oil Ass’n v. Hopkins","cite":"269 U.S. 110","y":1925,"id":"scdb/1925-004","sc":1,"by":{"0":"35","1":"41"},"q":[{"src":"brief","b":1,"text":"the power of Congress to determine how * * * income * * * shall be taxed.","cite":"269 U.S. 110, 114"}]},{"t":"case","label":"Chiafalo v. Washington","cite":"140 S. Ct. 2316","y":2020,"id":"2019/19-465","sc":1,"by":{"0":"26"}},{"t":"case","label":"Comm’r v. Banks","cite":"543 U.S. 426","y":2005,"id":"2004/03-892","sc":1,"by":{"0":"36","1":"13, 14, 33, 41","2":"10"},"q":[{"src":"brief","b":1,"text":"all economic gains not otherwise exempted,","cite":"543 U.S. 426, 433"}]},{"t":"case","label":"Comm’r v. Culbertson","cite":"337 U.S. 733","y":1949,"id":"scdb/1948-107","sc":1,"by":{"0":"28"}},{"t":"case","label":"Comm’r v. Glenshaw Glass Co.","cite":"348 U.S. 426","y":1955,"id":"scdb/1954-042","sc":1,"by":{"0":"24, 25, 28, 43","1":"12, 27, 38, 41","2":"4, 7, 8"}},{"t":"case","label":"Comm’r v. Indianapolis Power & Light Co.","cite":"493 U.S. 203","y":1990,"id":"1989/88-1319","sc":1,"by":{"0":"25, 36","1":"38","2":"8"}},{"t":"case","label":"Comm’r v. Kowalski","cite":"434 U.S. 77","y":1977,"id":"1977/76-1095","sc":1,"by":{"0":"25","1":"39"},"q":[{"src":"opinion","who":"Justice Barrett, concurring in the judgment","text":"`the full measure of [Congress's] taxing power.'","cite":"434 U. S. 77, 82"}]},{"t":"case","label":"Connecticut Gen. Life Ins. Co. v. Eaton","cite":"218 F. 188","y":1914,"court":"D. Conn.","url":"https://www.courtlistener.com/c/F./218/188/","by":{"0":"28"},"q":[{"src":"argument","who":"Mr. Grossman","text":"I mean, this was addressed and discussed at the Connecticut, the Pennsylvania, and the Virginia ratifying convention by James Madison, by Chief -- Chief Justice Marshall."}]},{"t":"case","label":"Corliss v. Bowers","cite":"281 U.S. 376","y":1930,"id":"scdb/1929-053","sc":1,"by":{"0":"24, 48"},"q":[{"src":"argument","who":"Mr. Grossman","text":"I think it can raise issues under both, but the Court has traditionally considered it to be a Sixteenth Amendment issue not only in Macomber but in trust cases like Corliss, where, again, the Court considered it a question of did the taxpayer have control over the -- over the -- its stream of income that he had in that case redirected into a trust for the benefit of his close family members."}]},{"t":"case","label":"Cullinan v. Walker","cite":"262 U.S. 134","y":1923,"id":"scdb/1922-170","sc":1,"by":{"0":"20"}},{"t":"case","label":"Diedrich v. Comm’r","cite":"457 U.S. 191","y":1982,"id":"1981/80-2204","sc":1,"by":{"0":"47"},"q":[{"src":"brief","b":0,"text":"This Court has recognized that ‘income’ may be realized by a variety of indirect means.","cite":"457 U.S. 191, 195"}]},{"t":"case","label":"Dobbs v. Jackson Women’s Health Org.","cite":"142 S. Ct. 2228","y":2022,"id":"2021/19-1392","sc":1,"by":{"0":"36"}},{"t":"case","label":"Dougherty v. Comm’r","cite":"60 T.C. 917","y":1973,"url":"https://www.courtlistener.com/c/T.C./60/917/","by":{"0":"51","1":"27, 44"}},{"t":"case","label":"Doyle v. Mitchell Bros. Co.","cite":"247 U.S. 179","y":1918,"id":"scdb/1917-168","sc":1,"by":{"0":"28"}},{"t":"case","label":"Eisner v. Macomber","cite":"252 U.S. 189","y":1920,"id":"scdb/1919-124","sc":1,"by":{"0":"1, 2, 13–15, 17–27, 33, 35–43, 47, 48, 50","1":"10, 11, 33-36","2":"2-10, 16, 18, 19, 21, 22, 25, 26"},"q":[{"src":"brief","b":0,"text":"received or drawn by the recipient (the taxpayer) for his separate use, benefit and disposal.","cite":"252 U.S. at 207"},{"src":"brief","b":0,"text":"not on unrealized appreciation of [the taxpayer’s] securities.","cite":"252 U.S. at 214"},{"src":"brief","b":1,"text":"the essential nature of a stock dividend necessarily prevents its being regarded as income in any true sense","cite":"252 U.S. at 205"},{"src":"brief","b":1,"text":"[i]ncome may be defined as the gain derived from capital, from labor, or from both combined.","cite":"252 U.S. at 207"},{"src":"brief","b":2,"text":"stockholder’s share in the accumulated profits of the company is capital, not income.","cite":"252 U.S. at 219"},{"src":"opinion","who":"Justice Barrett, concurring in the judgment","text":"income Barrett, J., concurring in judgment within the meaning of the Sixteenth Amendment.","cite":"252 U. S. 189, 211"},{"src":"opinion","who":"Justice Barrett, concurring in the judgment","text":"tax without apportionment a stockholder's interest in accumulated earnings prior to dividend declared,","cite":"252 U. S., at 218"},{"src":"opinion","who":"Justice Barrett, concurring in the judgment","text":"according to truth and substance, [not] form.","cite":"252 U. S., at 206"}]},{"t":"case","label":"Flint v. Stone Tracy Co.","cite":"220 U.S. 107","y":1911,"id":"scdb/1910-091","sc":1,"by":{"0":"53","1":"11, 47, 48","2":"16, 22, 25"},"q":[{"src":"brief","b":1,"text":"property solely because of its ownership.","cite":"220 U.S. at 150"},{"src":"brief","b":2,"text":"doing business in a certain way,","cite":"220 U.S. at 150"},{"src":"brief","b":2,"text":"imposed upon property simply because of its ownership.","cite":"220 U.S. at 150"},{"src":"argument","who":"Mr. Grossman","text":"That is the sort of tax that Flint, which I think is the high water mat -- mark of the Court's excise tax jurisprudence, indicates is, in fact, a tax on property and cannot be sustained as an excise tax."}]},{"t":"case","label":"Garlin v. Murphy","cite":"42 A.D.2d 30","y":1973,"court":"N.Y. App. Div. 3d","url":"https://www.courtlistener.com/c/A.D.2d/42/30/","by":{"0":"52"}},{"t":"case","label":"Garlock Inc. v. Comm’r","cite":"58 T.C. 423","y":1972,"url":"https://www.courtlistener.com/c/T.C./58/423/","by":{"0":"51"}},{"t":"case","label":"Gibbons v. Mahon","cite":"136 U.S. 549","y":1890,"id":"scdb/1889-287","sc":1,"by":{"0":"28","2":"18, 23"},"q":[{"src":"brief","b":2,"text":"remains the property of the corporation, and does not become the property of the stockholders, unless and until it is distributed.","cite":"136 U.S. 549, 557–58"},{"src":"argument","who":"Mr. Grossman","text":"But, with respect to income, going back to Gibbons versus Mahon, which recognized it as a well-established principle at that point that corporations are different in that respect from partnerships, indeed, that was the basis on which Macomber rejected the same -- the same argument."}]},{"t":"case","label":"Goesele v. Bimeler","cite":"55 U.S. 589","y":1852,"id":"scdb/1852-056","sc":1,"by":{"0":"41"}},{"t":"case","label":"Gray v. Darlington","cite":"82 U.S. 63","y":1872,"id":"scdb/1872-024","sc":1,"by":{"0":"27"}},{"t":"case","label":"Haynes v. United States","cite":"390 U.S. 85","y":1968,"id":"1967/236","sc":1,"by":{"0":"51"}},{"t":"case","label":"Heiner v. Mellon","cite":"304 U.S. 271","y":1938,"id":"scdb/1937-080","sc":1,"by":{"0":"41","1":"24, 42"},"q":[{"src":"brief","b":1,"text":"no distribution of profits could lawfully have been made","cite":"304 U.S. 271, 280"},{"src":"opinion","who":"Justice Thomas, dissenting","text":"reaffrmed that Congress may choose to tax either [a] partnership or [its] partners","cite":"304 U. S. 271"},{"src":"argument","who":"General Prelogar","text":"And so I think, looking at what is maybe the closest precedent to the situation that we have here, I'd point to the Court's decision in Heiner versus Mellon, which considered the propriety of the tax on partners even in a circumstance where they couldn't actually access the partnership income --"},{"src":"argument","who":"Justice Kavanaugh","text":"And the precedent most on point for you I think you said is Heiner, right, the partnership case?"},{"src":"argument","who":"General Prelogar","text":"It strongly supports the result in this case because, in Heiner, the Court confronted a situation where partners claimed they could not lawfully be taxed on partnership income on a pass-through basis because state law operated to preclude any distributions of that partnership income to them."}]},{"t":"case","label":"Helvering v. Bruun","cite":"309 U.S. 461","y":1940,"id":"scdb/1939-110","sc":1,"by":{"0":"23, 42","1":"36, 37","2":"6, 7"},"q":[{"src":"brief","b":0,"text":"a gain from capital investment which, when realized, by conversion into money or other property…has consistently been regarded as income within the meaning of the Sixteenth Amendment and taxable as such in the period when realized.","cite":"309 U.S. 461, 469"},{"src":"opinion","who":"Justice Jackson, concurring","text":"be able to sever . . . the gain from his original capital","cite":"309 U. S. 461, 469"},{"src":"opinion","who":"Justice Barrett, concurring in the judgment","text":"economic gain is not always taxable as income.","cite":"309 U. S., at 469"}]},{"t":"case","label":"Helvering v. Eubank","cite":"311 U.S. 122","y":1940,"id":"scdb/1940-012","sc":1,"by":{"0":"24"}},{"t":"case","label":"Helvering v. Gowran","cite":"302 U.S. 238","y":1937,"id":"scdb/1937-030","sc":1,"by":{"0":"21","1":"36"},"q":[{"src":"brief","b":1,"text":"no stock dividend could be taxed.","cite":"302 U.S. 238, 242"}]},{"t":"case","label":"Helvering v. Griffiths","cite":"318 U.S. 371","y":1943,"id":"scdb/1942-095","sc":1,"by":{"0":"22, 39, 43","1":"18, 35, 37","2":"6, 7"},"q":[{"src":"brief","b":0,"text":"not constitute income to the shareholder within the meaning of the sixteenth amendment to the Constitution.","cite":"318 U.S. 371, 383"},{"src":"brief","b":1,"text":"[it] do[es] not decide whether a tax may constitutionally be laid until [it] find[s] that Congress has laid it.","cite":"318 U.S. 371, 394"}]},{"t":"case","label":"Helvering v. Horst","cite":"311 U.S. 112","y":1940,"id":"scdb/1940-027","sc":1,"by":{"0":"23, 24, 42, 43","1":"8, 37, 39","2":"6"},"q":[{"src":"opinion","who":"Justice Barrett, concurring in the judgment","text":"the last step . . . by which [one] obtains the fruition of the economic gain which has already accrued to him.","cite":"311 U. S., at 115"}]},{"t":"case","label":"Helvering v. Indep. Life Ins. Co.","cite":"292 U.S. 371","y":1934,"id":"scdb/1933-128","sc":1,"by":{"0":"35"}},{"t":"case","label":"Helvering v. Sprouse","cite":"318 U.S. 604","y":1943,"id":"scdb/1942-118","sc":1,"by":{"0":"22"}},{"t":"case","label":"Ivan Allen Co. v. United States","cite":"422 U.S. 617","y":1975,"id":"1974/74-22","sc":1,"by":{"0":"25, 35, 38","2":"25"},"q":[{"src":"brief","b":0,"text":"[E]very Revenue Act since the adoption of the Sixteenth Amendment in 1913 has imposed a tax upon unnecessary accumulations of corporate earnings effected for the purpose of insulating shareholders","cite":"422 U.S. at 624"},{"src":"argument","who":"Mr. Grossman","text":"It's Ivan Allen."},{"src":"argument","who":"Mr. Grossman","text":"And so far as Macomber's rule is concerned -- and the Court has applied the dividing line recognized by Macomber as recently as 1975 in Ivan Allen and it's carried forward the same principle in cases like Indianapolis Power & Light in 1990, as well as restating it in Cottage Savings in 1991."}]},{"t":"case","label":"James v. United States","cite":"366 U.S. 213","y":1961,"id":"1960/63","sc":1,"by":{"0":"25","1":"39"}},{"t":"case","label":"Koshland v. Helvering","cite":"298 U.S. 441","y":1936,"id":"scdb/1935-065","sc":1,"by":{"0":"21, 22, 39","1":"36","2":"7"},"q":[{"src":"brief","b":1,"text":"the preexisting proportionate interests of the stockholders remained unaltered.","cite":"298 U.S. 441, 444-445"}]},{"t":"case","label":"Lynch v. Hornby","cite":"247 U.S. 339","y":1918,"id":"scdb/1917-145","sc":1,"by":{"0":"19","1":"34, 35","2":"18"}},{"t":"case","label":"MacLaughlin v. Alliance Ins. Co. of Philadelphia","cite":"286 U.S. 244","y":1932,"id":"scdb/1931-093","sc":1,"by":{"0":"23"},"q":[{"src":"brief","b":0,"text":"may be taxed, though it was in the making long before.","cite":"286 U.S. 244, 249"},{"src":"argument","who":"Mr. Grossman","text":"Respectfully, the Court has already said in multiple occasions that realization is, in fact, required for there to be income under the Sixteenth Amendment. It's not only Macomber. It's also MacLaughlin versus Alliance Insurance. It's the Safety Car Heating."}]},{"t":"case","label":"Mallory v. Norfolk S. Ry. Co.","cite":"143 S. Ct. 2028","y":2023,"id":"2022/21-1168","sc":1,"by":{"0":"44"}},{"t":"case","label":"Marr v. United States","cite":"268 U.S. 536","y":1925,"id":"scdb/1924-162","sc":1,"by":{"0":"21"}},{"t":"case","label":"Maryland Cas. Co. v. United States","cite":"52 Ct. Cl. 201","y":1917,"court":"Ct. Cl.","url":"https://www.courtlistener.com/c/Ct.%20Cl./52/201/","by":{"0":"27","1":"20"},"q":[{"src":"brief","b":0,"text":"courts…to include only the receipt of actual cash as opposed to contemplated revenue due but unpaid.","cite":"52 Ct. Cl. 201, 209"},{"src":"brief","b":1,"text":"the receipt of actual cash as opposed to contemplated revenue due but unpaid, unless a contrary purpose is manifest from the language of the statute.","cite":"52 Ct. Cl. 201, 209"}]},{"t":"case","label":"McDonald v. Maxwell","cite":"274 U.S. 91","y":1927,"id":"scdb/1926-051","sc":1,"by":{"0":"21"}},{"t":"case","label":"M.E. Blatt Co. v. United States","cite":"305 U.S. 267","y":1938,"id":"scdb/1938-013","sc":1,"by":{"0":"42"},"q":[{"src":"brief","b":0,"text":"the improvements increased the value of the building, that enhancement is not realized income of [the] lessor.","cite":"305 U.S. 267, 279"}]},{"t":"case","label":"Merchants’ Loan & Trust Co. v. Smietanka","cite":"255 U.S. 509","y":1921,"id":"scdb/1920-142","sc":1,"by":{"0":"33","2":"5, 12"},"q":[{"src":"brief","b":0,"text":"the commonly understood meaning of the term which must have been in the minds of the people when they adopted the Sixteenth Amendment to the Constitution.","cite":"255 U.S. 509, 519"}]},{"t":"case","label":"Merchants’ Nat’l Bank of Cincinnati v. Wehrmann","cite":"202 U.S. 295","y":1906,"id":"scdb/1905-118","sc":1,"by":{"0":"42","1":"25"}},{"t":"case","label":"Miles v. Safe Deposit & Trust Co. of Baltimore","cite":"259 U.S. 247","y":1922,"id":"scdb/1921-157","sc":1,"by":{"0":"21"}},{"t":"case","label":"Minot v. Paine","cite":"99 Mass. 101","y":1868,"url":"https://www.courtlistener.com/c/Mass./99/101/","by":{"0":"28","1":"20"}},{"t":"case","label":"Murphy v. United States","cite":"992 F.2d 929","y":1993,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/992/929/","by":{"0":"52"}},{"t":"case","label":"Mut. Ben. Life Ins. Co. v. Herold","cite":"198 F. 199","y":1912,"court":"D.N.J.","url":"https://www.courtlistener.com/c/F./198/199/","by":{"0":"27"}},{"t":"case","label":"Nat’l Fed’n of Indep. Bus. v. Sebelius","cite":"567 U.S. 519","y":2012,"id":"2011/11-393","sc":1,"by":{"0":"35","1":"3, 4","2":"5"},"q":[{"src":"brief","b":1,"text":"[A]ny ‘direct Tax’ must be apportioned so that each State pays in proportion to its population.","cite":"567 U.S. 519, 570"},{"src":"opinion","who":"Justice Barrett, concurring in the judgment","text":"without regard to property, profession, or any other circumstance.","cite":"567 U. S. 519, 571"},{"src":"opinion","who":"Justice Thomas, dissenting","text":"each State pays in proportion to its population.","cite":"567 U. S. 519, 570"}]},{"t":"case","label":"NLRB v. Noel Canning","cite":"573 U.S. 513","y":2014,"id":"2013/12-1281","sc":1,"by":{"0":"37, 47","1":"22, 26"},"q":[{"src":"brief","b":0,"text":"[l]ong settled and established practice is a consideration of great weight","cite":"573 U.S. 513, 524"},{"src":"brief","b":1,"text":"offers strong support for [a] broad[er] interpretation","cite":"573 U.S. 513, 528"}]},{"t":"case","label":"Pollock v. Farmers’ Loan & Trust Co.","cite":"157 U.S. 429","y":1895,"id":"1850-1900/157us429","sc":1,"by":{"0":"1, 5, 8, 19, 27, 34, 35"},"q":[{"src":"brief","b":0,"text":"There is no such thing in the theory of our national government as unlimited power of taxation.","cite":"157 U.S. 429, 599"}]},{"t":"case","label":"Rockefeller v. United States","cite":"257 U.S. 176","y":1921,"id":"scdb/1921-023","sc":1,"by":{"0":"20"}},{"t":"case","label":"Ross v. Comm’r","cite":"169 F.2d 483","y":1948,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/169/483/","by":{"0":"48"},"q":[{"src":"brief","b":0,"text":"treats as taxable income which is unqualifiedly subject to the demand of a taxpayer…, whether or not such income has actually been received in cash.","cite":"169 F.2d 483, 490"}]},{"t":"case","label":"S. Pac. Co. v. Lowe","cite":"247 U.S. 330","y":1918,"id":"scdb/1917-144","sc":1,"by":{"0":"48","2":"9"}},{"t":"case","label":"Stratton’s Indep., Ltd. v. Howbert","cite":"231 U.S. 399","y":1913,"id":"scdb/1913-043","sc":1,"by":{"0":"28","1":"47"},"q":[{"src":"brief","b":0,"text":"the gain derived from capital, from labor, or from both combined.","cite":"231 U.S. 399, 415"}]},{"t":"case","label":"Taft v. Bowers","cite":"278 U.S. 470","y":1929,"id":"scdb/1928-028","sc":1,"by":{"0":"22, 35","1":"33, 37, 42, 44, 45","2":"10"},"q":[{"src":"brief","b":1,"text":"There is nothing in the Constitution which lends support to the theory that gain actually resulting from the increased value of capital can be treated as taxable income in the hands of the recipient only so far as the increase occurred while he owned the property.","cite":"278 U.S. at 484"},{"src":"argument","who":"General Prelogar","text":"That was the holding in Taft versus Bowers, where the Court considered this issue with respect to the gift tax. It's also how Subpart F itself can operate."}]},{"t":"case","label":"United States v. Phellis","cite":"257 U.S. 156","y":1921,"id":"scdb/1921-022","sc":1,"by":{"0":"20","1":"35, 36"},"q":[{"src":"opinion","who":"Justice Barrett, concurring in the judgment","text":"a growth or increment of value in the investment.","cite":"257 U. S., at 169"},{"src":"argument","who":"Justice Gorsuch","text":"I think those were your words, \"misguided.\" I -- I look at Phellis, I look at Bruun, I look at Horst, and it seems to me at least as I read them that they're all trying to work within Macomber's framework and talking about is it fair to say that there was realization to the taxpayer, not realization somewhere back in the chain of history and income realized by the corporation or a parent or a subsidiary or whomever."},{"src":"argument","who":"Justice Gorsuch","text":"In Phellis, we said that we were following -- applying the tests laid down in Macomber. In Bruun, we said that -- that -- that it was -- it was following Macomber's understanding of income."}]},{"t":"case","label":"United States v. Safety Car Heating & Lighting Co.","cite":"297 U.S. 88","y":1936,"id":"scdb/1935-067","sc":1,"by":{"0":"23, 35","2":"21"},"q":[{"src":"brief","b":0,"text":"when through sale or conversion the increase was separated therefrom, it became income.","cite":"297 U.S. 88, 99"},{"src":"opinion","who":"Justice Barrett, concurring in the judgment","text":"Income within the meaning of the Sixteenth Amendment . . . is income as the word is known in the common speech of men.","cite":"297 U. S., at 99"},{"src":"argument","who":"Mr. Grossman","text":"Respectfully, the Court has already said in multiple occasions that realization is, in fact, required for there to be income under the Sixteenth Amendment. It's not only Macomber. It's also MacLaughlin versus Alliance Insurance. It's the Safety Car Heating."},{"src":"argument","who":"Mr. Grossman","text":"And then, finally, with respect to accrual, the Court already addressed that issue in the Safety Car Heating & Lighting case, where it held that standard Sixteenth Amendment realization principles -- and -- and it cited, among others, Macomber -- apply to the accrual method of accounting."}]},{"t":"case","label":"United States v. Schillinger","cite":"27 F. Cas. 973","y":1876,"court":"C.C.S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Cas./27/973/","by":{"0":"27","1":"20"}},{"t":"case","label":"Weiss v. Stearn","cite":"265 U.S. 242","y":1924,"id":"scdb/1923-154","sc":1,"by":{"0":"21, 55","1":"37"}},{"t":"case","label":"Whitlock’s Estate v. Comm’r","cite":"59 T.C. 490","y":1972,"url":"https://www.courtlistener.com/c/T.C./59/490/","by":{"0":"49"},"q":[{"src":"brief","b":0,"text":"interpose[d] [] a foreign corporate framework between themselves and [the] income.","cite":"59 T.C. 490, 507"}]},{"t":"const","label":"Amendment XVI","clauses":[["sixteenth-amendment","Sixteenth Amendment (Income Tax)"]],"text":"The Congress shall have power to lay and collect taxes on incomes, from whatever source derived, without apportionment among the several States, and without regard to any census or enumeration.","by":{"0":"4, 14, 17, 32, 34","2":"1, 3, 5, 6, 10, 16, 17, 21, 23, 24, 26"}},{"t":"const","label":"Article I, Section 2, Clause 3","clauses":[["apportionment","Apportionment and the Three-Fifths Clause"]],"text":"Representatives and direct Taxes shall be apportioned among the several States which may be included within this Union, according to their respective Numbers, which shall be determined by adding to the whole Number of free Persons, including those bound to Service for a Term of Years, and excluding Indians not taxed, three fifths of all other Persons. The actual Enumeration shall be made within three Years after the first Meeting of the Congress of the United States, and within every subsequent Term of ten Years, in such Manner as they shall by Law direct. The Number of Representatives shall not exceed one for every thirty Thousand, but each State shall have at Least one Representative; and until such enumeration shall be made, the State of New Hampshire shall be entitled to chuse three, Massachusetts eight, Rhode-Island and Providence Plantations one, Connecticut five, New-York six, New Jersey four, Pennsylvania eight, Delaware one, Maryland six, Virginia ten, North Carolina five, South Carolina five, and Georgia three.","by":{"0":"4, 12, 34"}},{"t":"const","label":"Article I, Section 9, Clause 4","text":"No Capitation, or other direct, Tax shall be laid, unless in Proportion to the Census or enumeration herein before directed to be taken.","by":{"0":"4, 12, 34, 36"}},{"t":"reg","label":"26 C.F.R. § 1.965-1","url":"https://www.ecfr.gov/current/title-26/section-1.965-1","by":{"0":"9"}},{"t":"usc","label":"26 U.S.C. § 61","url":"https://www.law.cornell.edu/uscode/text/26/61","subs":["(a)"],"stext":{"head":"§61. Gross income defined","paras":[[0,"(a) General definition"],[0,"Except as otherwise provided in this subtitle, gross income means all income from whatever source derived, including (but not limited to) the following items:"],[1,"(1) Compensation for services, including fees, commissions, fringe benefits, and similar items;"],[1,"(2) Gross income derived from business;"],[1,"(3) Gains derived from dealings in property;"],[1,"(4) Interest;"],[1,"(5) Rents;"],[1,"(6) Royalties;"],[1,"(7) Dividends;"],[1,"(8) Annuities;"],[1,"(9) Income from life insurance and endowment contracts;"],[1,"(10) Pensions;"],[1,"(11) Income from discharge of indebtedness;"],[1,"(12) Distributive share of partnership gross income;"],[1,"(13) Income in respect of a decedent; and"],[1,"(14) Income from an interest in an estate or trust."],[0,"(b) Cross references"],[2,"For items specifically included in gross income, see part II (sec. 71 and following). For items specifically excluded from gross income, see part III (sec. 101 and following)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/61?type=usc&year=mostrecent&link-type=html"},"by":{"0":"11, 37","1":"12, 39"},"q":[{"src":"brief","b":1,"text":"all income from whatever source derived,","cite":"26 U.S.C. 61(a)"}]},{"t":"usc","label":"26 U.S.C. § 245A","url":"https://www.law.cornell.edu/uscode/text/26/245A","subs":["(a)","(c)(1)(A)"],"by":{"0":"10","1":"5, 6, 5, 5"}},{"t":"usc","label":"26 U.S.C. § 305","url":"https://www.law.cornell.edu/uscode/text/26/305","subs":["(c)"],"stext":{"head":"§305. Distributions of stock and stock rights","paras":[[0,"(a) General rule"],[0,"Except as otherwise provided in this section, gross income does not include the amount of any distribution of the stock of a corporation made by such corporation to its shareholders with respect to its stock."],[0,"(b) Exceptions"],[0,"Subsection (a) shall not apply to a distribution by a corporation of its stock, and the distribution shall be treated as a distribution of property to which section 301 applies—"],[0,"(1) Distributions in lieu of money"],[1,"If the distribution is, at the election of any of the shareholders (whether exercised before or after the declaration thereof), payable either—"],[2,"(A) in its stock, or"],[2,"(B) in property."],[0,"(2) Disproportionate distributions"],[1,"If the distribution (or a series of distributions of which such distribution is one) has the result of—"],[2,"(A) the receipt of property by some shareholders, and"],[2,"(B) an increase in the proportionate interests of other shareholders in the assets or earnings and profits of the corporation."],[0,"(3) Distributions of common and preferred stock"],[1,"If the distribution (or a series of distributions of which such distribution is one) has the result of—"],[2,"(A) the receipt of preferred stock by some common shareholders, and"],[2,"(B) the receipt of common stock by other common shareholders."],[0,"(4) Distributions on preferred stock"],[1,"If the distribution is with respect to preferred stock, other than an increase in the conversion ratio of convertible preferred stock made solely to take account of a stock dividend or stock split with respect to the stock into which such convertible stock is convertible."],[0,"(5) Distributions of convertible preferred stock"],[1,"If the distribution is of convertible preferred stock, unless it is established to the satisfaction of the Secretary that such distribution will not have the result described in paragraph (2)."],[0,"(c) Certain transactions treated as distributions"],[0,"For purposes of this section and section 301, the Secretary shall prescribe regulations under which a change in conversion ratio, a change in redemption price, a difference between redemption price and issue price, a redemption which is treated as a distribution to which section 301 applies, or any transaction (including a recapitalization) having a similar effect on the interest of any shareholder shall be treated as a distribution with respect to any shareholder whose proportionate interest in the earnings and profits or assets of the corporation is increased by such change, difference, redemption, or similar transaction. Regulations prescribed under the preceding sentence shall provide that—"],[1,"(1) where the issuer of stock is required to redeem the stock at a specified time or the holder of stock has the option to require the issuer to redeem the stock, a redemption premium resulting from such requirement or option shall be treated as reasonable only if the amount of such premium does not exceed the amount determined under the principles of section 1273(a)(3),"],[1,"(2) a redemption premium shall not fail to be treated as a distribution (or series of distributions) merely because the stock is callable, and"],[1,"(3) in any case in which a redemption premium is treated as a distribution (or series of distributions), such premium shall be taken into account under principles similar to the principles of section 1272(a)."],[0,"(d) Definitions"],[0,"(1) Rights to acquire stock"],[1,"For purposes of this section, the term \"stock\" includes rights to acquire such stock."],[0,"(2) Shareholders"],[1,"For purposes of subsections (b) and (c), the term \"shareholder\" includes a holder of rights or of convertible securities."],[0,"(e) Treatment of purchaser of stripped preferred stock"],[0,"(1) In general"],[1,"If any person purchases after April 30, 1993, any stripped preferred stock, then such person, while holding such stock, shall include in gross income amounts equal to the amounts which would have been so includible if such stripped preferred stock were a bond issued on the purchase date and having original issue discount equal to the excess, if any, of—"],[2,"(A) the redemption price for such stock, over"],[2,"(B) the price at which such person purchased such stock."],[1,"The preceding sentence shall also apply in the case of any person whose basis in such stock is determined by reference to the basis in the hands of such purchaser."],[0,"(2) Basis adjustments"],[1,"Appropriate adjustments to basis shall be made for amounts includible in gross income under paragraph (1)."],[0,"(3) Tax treatment of person stripping stock"],[1,"If any person strips the rights to 1 or more dividends from any stock described in paragraph (5)(B) and after April 30, 1993, disposes of such dividend rights, for purposes of paragraph (1), such person shall be treated as having purchased the stripped preferred stock on the date of such disposition for a purchase price equal to such person's adjusted basis in such stripped preferred stock."],[0,"(4) Amounts treated as ordinary income"],[1,"Any amount included in gross income under paragraph (1) shall be treated as ordinary income."],[0,"(5) Stripped preferred stock"],[1,"For purposes of this subsection—"],[0,"(A) In general"],[2,"The term \"stripped preferred stock\" means any stock described in subparagraph (B) if there has been a separation in ownership between such stock and any dividend on such stock which has not become payable."],[0,"(B) Description of stock"],[2,"Stock is described in this subsection if such stock—"],[3,"(i) is limited and preferred as to dividends and does not participate in corporate growth to any significant extent, and"],[3,"(ii) has a fixed redemption price."],[0,"(6) Purchase"],[1,"For purposes of this subsection, the term \"purchase\" means—"],[2,"(A) any acquisition of stock, where"],[2,"(B) the basis of such stock is not determined in whole or in part by the reference to the adjusted basis of such stock in the hands of the person from whom acquired."],[0,"(7) Cross reference"],[2,"For treatment of stripped interests in certain accounts or entities holding preferred stock, see section 1286(e)."],[0,"(f) Cross references"],[1,"For special rules—"],[2,"(1) Relating to the receipt of stock and stock rights in corporate organizations and reorganizations, see part III (sec. 351 and following)."],[2,"(2) In the case of a distribution which results in a gift, see section 2501 and following."],[2,"(3) In the case of a distribution which has the effect of the payment of compensation, see section 61(a)(1)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/305?type=usc&year=mostrecent&link-type=html"},"by":{"0":"39","1":"31"}},{"t":"usc","label":"26 U.S.C. § 475","url":"https://www.law.cornell.edu/uscode/text/26/475","subs":["(a)"],"by":{"0":"52","1":"31"}},{"t":"usc","label":"26 U.S.C. § 531","url":"https://www.law.cornell.edu/uscode/text/26/531","by":{"0":"39"}},{"t":"usc","label":"26 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/26/701","by":{"0":"51"}},{"t":"usc","label":"26 U.S.C. § 702","url":"https://www.law.cornell.edu/uscode/text/26/702","subs":["(a)","(b)"],"by":{"0":"51","1":"29, 29"}},{"t":"usc","label":"26 U.S.C. § 817A","url":"https://www.law.cornell.edu/uscode/text/26/817A","subs":["(b)"],"by":{"0":"52, 53","1":"31"}},{"t":"usc","label":"26 U.S.C. § 877A","url":"https://www.law.cornell.edu/uscode/text/26/877A","subs":["(a)","(a)(1)","(b)(1)","(b)(4)(A)"],"stext":{"head":"§877A. Tax responsibilities of expatriation","paras":[[0,"(a) General rules"],[0,"For purposes of this subtitle—"],[0,"(1) Mark to market"],[1,"All property of a covered expatriate shall be treated as sold on the day before the expatriation date for its fair market value."],[0,"(2) Recognition of gain or loss"],[1,"In the case of any sale under paragraph (1)—"],[2,"(A) notwithstanding any other provision of this title, any gain arising from such sale shall be taken into account for the taxable year of the sale, and"],[2,"(B) any loss arising from such sale shall be taken into account for the taxable year of the sale to the extent otherwise provided by this title, except that section 1091 shall not apply to any such loss."],[1,"Proper adjustment shall be made in the amount of any gain or loss subsequently realized for gain or loss taken into account under the preceding sentence, determined without regard to paragraph (3)."],[0,"(3) Exclusion for certain gain"],[0,"(A) In general"],[2,"The amount which would (but for this paragraph) be includible in the gross income of any individual by reason of paragraph (1) shall be reduced (but not below zero) by $600,000."],[0,"(B) Adjustment for inflation"],[0,"(i) In general"],[3,"In the case of any taxable year beginning in a calendar year after 2008, the dollar amount in subparagraph (A) shall be increased by an amount equal to—"],[4,"(I) such dollar amount, multiplied by"],[4,"(II) the cost-of-living adjustment determined under section 1(f)(3) for the calendar year in which the taxable year begins, by substituting \"calendar year 2007\" for \"calendar year 2016\" in subparagraph (A)(ii) thereof."],[0,"(ii) Rounding"],[3,"If any amount as adjusted under clause (i) is not a multiple of $1,000, such amount shall be rounded to the nearest multiple of $1,000."],[0,"(b) Election to defer tax"],[0,"(1) In general"],[1,"If the taxpayer elects the application of this subsection with respect to any property treated as sold by reason of subsection (a), the time for payment of the additional tax attributable to such property shall be extended until the due date of the return for the taxable year in which such property is disposed of (or, in the case of property disposed of in a transaction in which gain is not recognized in whole or in part, until such other date as the Secretary may prescribe)."],[0,"(2) Determination of tax with respect to property"],[1,"For purposes of paragraph (1), the additional tax attributable to any property is an amount which bears the same ratio to the additional tax imposed by this chapter for the taxable year solely by reason of subsection (a) as the gain taken into account under subsection (a) with respect to such property bears to the total gain taken into account under subsection (a) with respect to all property to which subsection (a) applies."],[0,"(3) Termination of extension"],[1,"The due date for payment of tax may not be extended under this subsection later than the due date for the return of tax imposed by this chapter for the taxable year which includes the date of death of the expatriate (or, if earlier, the time that the security provided with respect to the property fails to meet the requirements of paragraph (4), unless the taxpayer corrects such failure within the time specified by the Secretary)."],[0,"(4) Security"],[0,"(A) In general"],[2,"No election may be made under paragraph (1) with respect to any property unless adequate security is provided with respect to such property."],[0,"(B) Adequate security"],[2,"For purposes of subparagraph (A), security with respect to any property shall be treated as adequate security if—"],[3,"(i) it is a bond which is furnished to, and accepted by, the Secretary, which is conditioned on the payment of tax (and interest thereon), and which meets the requirements of section 6325, or"],[3,"(ii) it is another form of security for such payment (including letters of credit) that meets such requirements as the Secretary may prescribe."],[0,"(5) Waiver of certain rights"],[1,"No election may be made under paragraph (1) unless the taxpayer makes an irrevocable waiver of any right under any treaty of the United States which would preclude assessment or collection of any tax imposed by reason of this section."],[0,"(6) Elections"],[1,"An election under paragraph (1) shall only apply to property described in the election and, once made, is irrevocable."],[0,"(7) Interest"],[1,"For purposes of section 6601, the last date for the payment of tax shall be determined without regard to the election under this subsection."],[0,"(c) Exception for certain property"],[0,"Subsection (a) shall not apply to—"],[1,"(1) any deferred compensation item (as defined in subsection (d)(4)),"],[1,"(2) any specified tax deferred account (as defined in subsection (e)(2)), and"],[1,"(3) any interest in a nongrantor trust (as defined in subsection (f)(3))."],[0,"(d) Treatment of deferred compensation items"],[0,"(1) Withholding on eligible deferred compensation items"],[0,"(A) In general"],[2,"In the case of any eligible deferred compensation item, the payor shall deduct and withhold from any taxable payment to a covered expatriate with respect to such item a tax equal to 30 percent thereof."],[0,"(B) Taxable payment"],[2,"For purposes of subparagraph (A), the term \"taxable payment\" means with respect to a covered expatriate any payment to the extent it would be includible in the gross income of the covered expatriate if such expatriate continued to be subject to tax as a citizen or resident of the United States. A deferred compensation item shall be taken into account as a payment under the preceding sentence when such item would be so includible."],[0,"(2) Other deferred compensation items"],[1,"In the case of any deferred compensation item which is not an eligible deferred compensation item—"],[2,"(A)(i) with respect to any deferred compensation item to which clause (ii) does not apply, an amount equal to the present value of the covered expatriate's accrued benefit shall be treated as having been received by such individual on the day before the expatriation date as a distribution under the plan, and"],[2,"(ii) with respect to any deferred compensation item referred to in paragraph (4)(D), the rights of the covered expatriate to such item shall be treated as becoming transferable and not subject to a substantial risk of forfeiture on the day before the expatriation date,"],[2,"(B) no early distribution tax shall apply by reason of such treatment, and"],[2,"(C) appropriate adjustments shall be made to subsequent distributions from the plan to reflect such treatment."],[0,"(3) Eligible deferred compensation items"],[1,"For purposes of this subsection, the term \"eligible deferred compensation item\" means any deferred compensation item with respect to which—"],[2,"(A) the payor of such item is—"],[3,"(i) a United States person, or"],[3,"(ii) a person who is not a United States person but who elects to be treated as a United States person for purposes of paragraph (1) and meets such requirements as the Secretary may provide to ensure that the payor will meet the requirements of paragraph (1), and"],[2,"(B) the covered expatriate—"],[3,"(i) notifies the payor of his status as a covered expatriate, and"],[3,"(ii) makes an irrevocable waiver of any right to claim any reduction under any treaty with the United States in withholding on such item."],[0,"(4) Deferred compensation item"],[1,"For purposes of this subsection, the term \"deferred compensation item\" means—"],[2,"(A) any interest in a plan or arrangement described in section 219(g)(5),"],[2,"(B) any interest in a foreign pension plan or similar retirement arrangement or program,"],[2,"(C) any item of deferred compensation, and"],[2,"(D) any property, or right to property, which the individual is entitled to receive in connection with the performance of services to the extent not previously taken into account under section 83 or in accordance with section 83."],[0,"(5) Exception"],[1,"Paragraphs (1) and (2) shall not apply to any deferred compensation item to the extent attributable to services performed outside the United States while the covered expatriate was not a citizen or resident of the United States."],[0,"(6) Special rules"],[0,"(A) Application of withholding rules"],[2,"Rules similar to the rules of subchapter B of chapter 3 shall apply for purposes of this subsection."],[0,"(B) Application of tax"],[2,"Any item subject to the withholding tax imposed under paragraph (1) shall be subject to tax under section 871."],[0,"(C) Coordination with other withholding requirements"],[2,"Any item subject to withholding under paragraph (1) shall not be subject to withholding under section 1441 or chapter 24."],[0,"(e) Treatment of specified tax deferred accounts"],[0,"(1) Account treated as distributed"],[1,"In the case of any interest in a specified tax deferred account held by a covered expatriate on the day before the expatriation date—"],[2,"(A) the covered expatriate shall be treated as receiving a distribution of his entire interest in such account on the day before the expatriation date,"],[2,"(B) no early distribution tax shall apply by reason of such treatment, and"],[2,"(C) appropriate adjustments shall be made to subsequent distributions from the account to reflect such treatment."],[0,"(2) Specified tax deferred account"],[1,"For purposes of paragraph (1), the term \"specified tax deferred account\" means an individual retirement plan (as defined in section 7701(a)(37)) other than any arrangement described in subsection (k) or (p) of section 408, a qualified tuition program (as defined in section 529), a qualified ABLE program (as defined in section 529A), a Coverdell education savings account (as defined in section 530), a health savings account (as defined in section 223), and an Archer MSA (as defined in section 220)."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/877A?type=usc&year=mostrecent&link-type=html"},"by":{"0":"52","1":"30, 31, 31, 31","2":"21"},"q":[{"src":"brief","b":0,"text":"until the due date of the return for the taxable year in which such property is disposed of,","cite":"26 U.S.C. § 877A(b)(1)"},{"src":"brief","b":1,"text":"on the day before the expatriation date,","cite":"26 U.S.C. 877A(a)(1)"}]},{"t":"usc","label":"26 U.S.C. § 951","url":"https://www.law.cornell.edu/uscode/text/26/951","subs":["(a)(1)","(a)(1)(A)","(b)"],"stext":{"head":"§951. Amounts included in gross income of United States shareholders","paras":[[0,"(a) Amounts included"],[0,"(1) In general"],[1,"If a foreign corporation is a controlled foreign corporation at any time during any taxable year, every person who is a United States shareholder (as defined in subsection (b)) of such corporation and who owns (within the meaning of section 958(a)) stock in such corporation on the last day, in such year, on which such corporation is a controlled foreign corporation shall include in his gross income, for his taxable year in which or with which such taxable year of the corporation ends—"],[2,"(A) his pro rata share (determined under paragraph (2)) of the corporation's subpart F income for such year, and"],[2,"(B) the amount determined under section 956 with respect to such shareholder for such year (but only to the extent not excluded from gross income under section 959(a)(2))."],[0,"(2) Pro rata share of subpart F income"],[1,"The pro rata share referred to in paragraph (1)(A)(i) in the case of any United States shareholder is the amount—"],[2,"(A) which would have been distributed with respect to the stock which such shareholder owns (within the meaning of section 958(a)) in such corporation if on the last day, in its taxable year, on which the corporation is a controlled foreign corporation it had distributed pro rata to its shareholders an amount (i) which bears the same ratio to its subpart F income for the taxable year, as (ii) the part of such year during which the corporation is a controlled foreign corporation bears to the entire year, reduced by"],[2,"(B) the amount of distributions received by any other person during such year as a dividend with respect to such stock, but only to the extent of the dividend which would have been received if the distribution by the corporation had been the amount (i) which bears the same ratio to the subpart F income of such corporation for the taxable year, as (ii) the part of such year during which such shareholder did not own (within the meaning of section 958(a)) such stock bears to the entire year."],[1,"For purposes of subparagraph (B), any gain included in the gross income of any person as a dividend under section 1248 shall be treated as a distribution received by such person with respect to the stock involved."],[0,"(b) United States shareholder defined"],[0,"For purposes of this title, the term \"United States shareholder\" means, with respect to any foreign corporation, a United States person (as defined in section 957(c)) who owns (within the meaning of section 958(a)), or is considered as owning by applying the rules of ownership of section 958(b), 10 percent or more of the total combined voting power of all classes of stock entitled to vote of such foreign corporation, or 10 percent or more of the total value of shares of all classes of stock of such foreign corporation."],[0,"(c) Coordination with passive foreign investment company provisions"],[0,"If, but for this subsection, an amount would be included in the gross income of a United States shareholder for any taxable year both under subsection (a)(1)(A)(i) and under section 1293 (relating to current taxation of income from certain passive foreign investment companies), such amount shall be included in the gross income of such shareholder only under subsection (a)(1)(A)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/951?type=usc&year=mostrecent&link-type=html"},"by":{"0":"10","1":"4-7, 10, 26-29, 32, 40, 42-44, 46, 49, 28, 28, 28"},"q":[{"src":"brief","b":1,"text":"include in [their] gross income * * * [their] pro rata share * * * of the [CFC’s] subpart F income for [the] year.","cite":"26 U.S.C. 951(a)(1)(A)"},{"src":"brief","b":1,"text":"subpart F income for [the] year.","cite":"26 U.S.C. 951(a)(1)(A)"}]},{"t":"usc","label":"26 U.S.C. § 952","url":"https://www.law.cornell.edu/uscode/text/26/952","by":{"0":"45","1":"28"}},{"t":"usc","label":"26 U.S.C. § 953","url":"https://www.law.cornell.edu/uscode/text/26/953","by":{"0":"45"}},{"t":"usc","label":"26 U.S.C. § 954","url":"https://www.law.cornell.edu/uscode/text/26/954","by":{"0":"45"}},{"t":"usc","label":"26 U.S.C. § 957","url":"https://www.law.cornell.edu/uscode/text/26/957","subs":["(a)"],"by":{"0":"9","1":"39"}},{"t":"usc","label":"26 U.S.C. § 965","url":"https://www.law.cornell.edu/uscode/text/26/965","subs":["(a)","(a)(1)","(a)(2)","(c)","(e)(1)(B)","(h)"],"stext":{"head":"§965. Treatment of deferred foreign income upon transition to participation exemption system of taxation","paras":[[0,"(a) Treatment of deferred foreign income as subpart F income"],[0,"In the case of the last taxable year of a deferred foreign income corporation which begins before January 1, 2018, the subpart F income of such foreign corporation (as otherwise determined for such taxable year under section 952) shall be increased by the greater of—"],[1,"(1) the accumulated post-1986 deferred foreign income of such corporation determined as of November 2, 2017, or"],[1,"(2) the accumulated post-1986 deferred foreign income of such corporation determined as of December 31, 2017."],[0,"(b) Reduction in amounts included in gross income of United States shareholders of specified foreign corporations with deficits in earnings and profits"],[0,"(1) In general"],[1,"In the case of a taxpayer which is a United States shareholder with respect to at least one deferred foreign income corporation and at least one E&P deficit foreign corporation, the amount which would (but for this subsection) be taken into account under section 951(a)(1) by reason of subsection (a) as such United States shareholder's pro rata share of the subpart F income of each deferred foreign income corporation shall be reduced by the amount of such United States shareholder's aggregate foreign E&P deficit which is allocated under paragraph (2) to such deferred foreign income corporation."],[0,"(2) Allocation of aggregate foreign E&P deficit"],[1,"The aggregate foreign E&P deficit of any United States shareholder shall be allocated among the deferred foreign income corporations of such United States shareholder in an amount which bears the same proportion to such aggregate as—"],[2,"(A) such United States shareholder's pro rata share of the accumulated post-1986 deferred foreign income of each such deferred foreign income corporation, bears to"],[2,"(B) the aggregate of such United States shareholder's pro rata share of the accumulated post-1986 deferred foreign income of all deferred foreign income corporations of such United States shareholder."],[0,"(3) Definitions related to E&P deficits"],[1,"For purposes of this subsection—"],[0,"(A) Aggregate foreign E&P deficit"],[0,"(i) In general"],[3,"The term \"aggregate foreign E&P deficit\" means, with respect to any United States shareholder, the lesser of—"],[4,"(I) the aggregate of such shareholder's pro rata shares of the specified E&P deficits of the E&P deficit foreign corporations of such shareholder, or"],[4,"(II) the amount determined under paragraph (2)(B)."],[0,"(ii) Allocation of deficit"],[3,"If the amount described in clause (i)(II) is less than the amount described in clause (i)(I), then the shareholder shall designate, in such form and manner as the Secretary determines—"],[4,"(I) the amount of the specified E&P deficit which is to be taken into account for each E&P deficit corporation with respect to the taxpayer, and"],[4,"(II) in the case of an E&P deficit corporation which has a qualified deficit (as defined in section 952), the portion (if any) of the deficit taken into account under subclause (I) which is attributable to a qualified deficit, including the qualified activities to which such portion is attributable."],[0,"(B) E&P deficit foreign corporation"],[2,"The term \"E&P deficit foreign corporation\" means, with respect to any taxpayer, any specified foreign corporation with respect to which such taxpayer is a United States shareholder, if, as of November 2, 2017—"],[3,"(i) such specified foreign corporation has a deficit in post-1986 earnings and profits,"],[3,"(ii) such corporation was a specified foreign corporation, and"],[3,"(iii) such taxpayer was a United States shareholder of such corporation."],[0,"(C) Specified E&P deficit"],[2,"The term \"specified E&P deficit\" means, with respect to any E&P deficit foreign corporation, the amount of the deficit referred to in subparagraph (B)."],[0,"(4) Treatment of earnings and profits in future years"],[0,"(A) Reduced earnings and profits treated as previously taxed income when distributed"],[2,"For purposes of applying section 959 in any taxable year beginning with the taxable year described in subsection (a), with respect to any United States shareholder of a deferred foreign income corporation, an amount equal to such shareholder's reduction under paragraph (1) which is allocated to such deferred foreign income corporation under this subsection shall be treated as an amount which was included in the gross income of such United States shareholder under section 951(a)."],[0,"(B) E&P deficits"],[2,"For purposes of this title, with respect to any taxable year beginning with the taxable year described in subsection (a), a United States shareholder's pro rata share of the earnings and profits of any E&P deficit foreign corporation under this subsection shall be increased by the amount of the specified E&P deficit of such corporation taken into account by such shareholder under paragraph (1), and, for purposes of section 952, such increase shall be attributable to the same activity to which the deficit so taken into account was attributable."],[0,"(5) Netting among United States shareholders in same affiliated group"],[0,"(A) In general"],[2,"In the case of any affiliated group which includes at least one E&P net surplus shareholder and one E&P net deficit shareholder, the amount which would (but for this paragraph) be taken into account under section 951(a)(1) by reason of subsection (a) by each such E&P net surplus shareholder shall be reduced (but not below zero) by such shareholder's applicable share of the affiliated group's aggregate unused E&P deficit."],[0,"(B) E&P net surplus shareholder"],[2,"For purposes of this paragraph, the term \"E&P net surplus shareholder\" means any United States shareholder which would (determined without regard to this paragraph) take into account an amount greater than zero under section 951(a)(1) by reason of subsection (a)."],[0,"(C) E&P net deficit shareholder"],[2,"For purposes of this paragraph, the term \"E&P net deficit shareholder\" means any United States shareholder if—"],[3,"(i) the aggregate foreign E&P deficit with respect to such shareholder (as defined in paragraph (3)(A) without regard to clause (i)(II) thereof), exceeds"],[3,"(ii) the amount which would (but for this subsection) be taken into account by such shareholder under section 951(a)(1) by reason of subsection (a)."],[0,"(D) Aggregate unused E&P deficit"],[2,"For purposes of this paragraph—"],[0,"(i) In general"],[3,"The term \"aggregate unused E&P deficit\" means, with respect to any affiliated group, the lesser of—"],[4,"(I) the sum of the excesses described in subparagraph (C), determined with respect to each E&P net deficit shareholder in such group, or"],[4,"(II) the amount determined under subparagraph (E)(ii)."],[0,"(ii) Reduction with respect to E&P net deficit shareholders which are not wholly owned by the affiliated group"],[3,"If the group ownership percentage of any E&P net deficit shareholder is less than 100 percent, the amount of the excess described in subparagraph (C) which is taken into account under clause (i)(I) with respect to such E&P net deficit shareholder shall be such group ownership percentage of such amount."],[0,"(E) Applicable share"],[2,"For purposes of this paragraph, the term \"applicable share\" means, with respect to any E&P net surplus shareholder in any affiliated group, the amount which bears the same proportion to such group's aggregate unused E&P deficit as—"],[3,"(i) the product of—"],[4,"(I) such shareholder's group ownership percentage, multiplied by"],[4,"(II) the amount which would (but for this paragraph) be taken into account under section 951(a)(1) by reason of subsection (a) by such shareholder, bears to"],[3,"(ii) the aggregate amount determined under clause (i) with respect to all E&P net surplus shareholders in such group."],[0,"(F) Group ownership percentage"],[2,"For purposes of this paragraph, the term \"group ownership percentage\" means, with respect to any United States shareholder in any affiliated group, the percentage of the value of the stock of such United States shareholder which is held by other includible corporations in such affiliated group. Notwithstanding the preceding sentence, the group ownership percentage of the common parent of the affiliated group is 100 percent. Any term used in this subparagraph which is also used in section 1504 shall have the same meaning as when used in such section."],[0,"(c) Application of participation exemption to included income"],[0,"(1) In general"],[1,"In the case of a United States shareholder of a deferred foreign income corporation, there shall be allowed as a deduction for the taxable year in which an amount is included in the gross income of such United States shareholder under section 951(a)(1) by reason of this section an amount equal to the sum of—"],[2,"(A) the United States shareholder's 8 percent rate equivalent percentage of the excess (if any) of—"],[3,"(i) the amount so included as gross income, over"],[3,"(ii) the amount of such United States shareholder's aggregate foreign cash position, plus"],[2,"(B) the United States shareholder's 15.5 percent rate equivalent percentage of so much of the amount described in subparagraph (A)(ii) as does not exceed the amount described in subparagraph (A)(i)."],[0,"(2) 8 and 15.5 percent rate equivalent percentages"],[1,"For purposes of this subsection—"],[0,"(A) 8 percent rate equivalent percentage"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/965?type=usc&year=mostrecent&link-type=html"},"by":{"0":"9, 10, 44, 46","1":"39, 39, 39, 39, 39, 39, 39"},"q":[{"src":"brief","b":0,"text":"the last taxable year of [the] corporation which begins before January 1, 2018,","cite":"26 U.S.C. § 965(a)"},{"src":"brief","b":1,"text":"any foreign corporation with respect to which one or more domestic corporations is a [10%] shareholder.","cite":"26 U.S.C. 965(e)(1)(B)"}]},{"t":"usc","label":"26 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/26/1001","subs":["(a)"],"by":{"0":"38","1":"39"}},{"t":"usc","label":"26 U.S.C. § 1256","url":"https://www.law.cornell.edu/uscode/text/26/1256","subs":["(a)","(b)"],"by":{"0":"52","1":"31, 31"}},{"t":"usc","label":"26 U.S.C. § 1362","url":"https://www.law.cornell.edu/uscode/text/26/1362","subs":["(a)","(d)(1)(B)"],"stext":{"head":"§1362. Election; revocation; termination","paras":[[0,"(a) Election"],[0,"(1) In general"],[1,"Except as provided in subsection (g), a small business corporation may elect, in accordance with the provisions of this section, to be an S corporation."],[0,"(2) All shareholders must consent to election"],[1,"An election under this subsection shall be valid only if all persons who are shareholders in such corporation on the day on which such election is made consent to such election."],[0,"(b) When made"],[0,"(1) In general"],[1,"An election under subsection (a) may be made by a small business corporation for any taxable year—"],[2,"(A) at any time during the preceding taxable year, or"],[2,"(B) at any time during the taxable year and on or before the 15th day of the 3d month of the taxable year."],[0,"(2) Certain elections made during 1st 2½ months treated as made for next taxable year"],[1,"If—"],[2,"(A) an election under subsection (a) is made for any taxable year during such year and on or before the 15th day of the 3d month of such year, but"],[2,"(B) either—"],[3,"(i) on 1 or more days in such taxable year before the day on which the election was made the corporation did not meet the requirements of subsection (b) of section 1361, or"],[3,"(ii) 1 or more of the persons who held stock in the corporation during such taxable year and before the election was made did not consent to the election,"],[1,"then such election shall be treated as made for the following taxable year."],[0,"(3) Election made after 1st 2½ months treated as made for following taxable year"],[1,"If—"],[2,"(A) a small business corporation makes an election under subsection (a) for any taxable year, and"],[2,"(B) such election is made after the 15th day of the 3d month of the taxable year and on or before the 15th day of the 3rd month of the following taxable year,"],[1,"then such election shall be treated as made for the following taxable year."],[0,"(4) Taxable years of 2½ months or less"],[1,"For purposes of this subsection, an election for a taxable year made not later than 2 months and 15 days after the first day of the taxable year shall be treated as timely made during such year."],[0,"(5) Authority to treat late elections, etc., as timely"],[1,"If—"],[2,"(A) an election under subsection (a) is made for any taxable year (determined without regard to paragraph (3)) after the date prescribed by this subsection for making such election for such taxable year or no such election is made for any taxable year, and"],[2,"(B) the Secretary determines that there was reasonable cause for the failure to timely make such election,"],[1,"the Secretary may treat such an election as timely made for such taxable year (and paragraph (3) shall not apply)."],[0,"(c) Years for which effective"],[0,"An election under subsection (a) shall be effective for the taxable year of the corporation for which it is made and for all succeeding taxable years of the corporation, until such election is terminated under subsection (d)."],[0,"(d) Termination"],[0,"(1) By revocation"],[0,"(A) In general"],[2,"An election under subsection (a) may be terminated by revocation."],[0,"(B) More than one-half of shares must consent to revocation"],[2,"An election may be revoked only if shareholders holding more than one-half of the shares of stock of the corporation on the day on which the revocation is made consent to the revocation."],[0,"(C) When effective"],[2,"Except as provided in subparagraph (D)—"],[3,"(i) a revocation made during the taxable year and on or before the 15th day of the 3d month thereof shall be effective on the 1st day of such taxable year, and"],[3,"(ii) a revocation made during the taxable year but after such 15th day shall be effective on the 1st day of the following taxable year."],[0,"(D) Revocation may specify prospective date"],[2,"If the revocation specifies a date for revocation which is on or after the day on which the revocation is made, the revocation shall be effective on and after the date so specified."],[0,"(2) By corporation ceasing to be small business corporation"],[0,"(A) In general"],[2,"An election under subsection (a) shall be terminated whenever (at any time on or after the 1st day of the 1st taxable year for which the corporation is an S corporation) such corporation ceases to be a small business corporation."],[0,"(B) When effective"],[2,"Any termination under this paragraph shall be effective on and after the date of cessation."],[0,"(3) Where passive investment income exceeds 25 percent of gross receipts for 3 consecutive taxable years and corporation has accumulated earnings and profits"],[0,"(A) Termination"],[0,"(i) In general"],[3,"An election under subsection (a) shall be terminated whenever the corporation—"],[4,"(I) has accumulated earnings and profits at the close of each of 3 consecutive taxable years, and"],[4,"(II) has gross receipts for each of such taxable years more than 25 percent of which are passive investment income."],[0,"(ii) When effective"],[3,"Any termination under this paragraph shall be effective on and after the first day of the first taxable year beginning after the third consecutive taxable year referred to in clause (i)."],[0,"(iii) Years taken into account"],[3,"A prior taxable year shall not be taken into account under clause (i) unless the corporation was an S corporation for such taxable year."],[0,"(B) Gross receipts from the sales of certain assets"],[2,"For purposes of this paragraph—"],[3,"(i) in the case of dispositions of capital assets (other than stock and securities), gross receipts from such dispositions shall be taken into account only to the extent of the capital gain net income therefrom, and"],[3,"(ii) in the case of sales or exchanges of stock or securities, gross receipts shall be taken into account only to the extent of the gains therefrom."],[0,"(C) Passive investment income defined"],[0,"(i) In general"],[3,"Except as otherwise provided in this subparagraph, the term \"passive investment income\" means gross receipts derived from royalties, rents, dividends, interest, and annuities."],[0,"(ii) Exception for interest on notes from sales of inventory"],[3,"The term \"passive investment income\" shall not include interest on any obligation acquired in the ordinary course of the corporation's trade or business from its sale of property described in section 1221(a)(1)."],[0,"(iii) Treatment of certain lending or finance companies"],[3,"If the S corporation meets the requirements of section 542(c)(6) for the taxable year, the term \"passive investment income\" shall not include gross receipts for the taxable year which are derived directly from the active and regular conduct of a lending or finance business (as defined in section 542(d)(1))."],[0,"(iv) Treatment of certain dividends"],[3,"If an S corporation holds stock in a C corporation meeting the requirements of section 1504(a)(2), the term \"passive investment income\" shall not include dividends from such C corporation to the extent such dividends are attributable to the earnings and profits of such C corporation derived from the active conduct of a trade or business."],[0,"(v) Exception for banks, etc."],[3,"In the case of a bank (as defined in section 581) or a depository institution holding company (as defined in section 3(w)(1) of the Federal Deposit Insurance Act (12 U.S.C. 1813(w)(1))), the term \"passive investment income\" shall not include—"],[4,"(I) interest income earned by such bank or company, or"],[4,"(II) dividends on assets required to be held by such bank or company, including stock in the Federal Reserve Bank, the Federal Home Loan Bank, or the Federal Agricultural Mortgage Bank or participation certificates issued by a Federal Intermediate Credit Bank."],[0,"(e) Treatment of S termination year"],[0,"(1) In general"],[1,"In the case of an S termination year, for purposes of this title—"],[0,"(A) S short year"],[2,"The portion of such year ending before the 1st day for which the termination is effective shall be treated as a short taxable year for which the corporation is an S corporation."],[0,"(B) C short year"],[2,"The portion of such year beginning on such 1st day shall be treated as a short taxable year for which the corporation is a C corporation."],[0,"(2) Pro rata allocation"],[1,"Except as provided in paragraph (3) and subparagraphs (C) and (D) of paragraph (6), the determination of which items are to be taken into account for each of the short taxable years referred to in paragraph (1) shall be made—"],[2,"(A) first by determining for the S termination year—"],[3,"(i) the amount of each of the items of income, loss, deduction, or credit described in section 1366(a)(1)(A), and"],[3,"(ii) the amount of the nonseparately computed income or loss, and"],[2,"(B) then by assigning an equal portion of each amount determined under subparagraph (A) to each day of the S termination year."],[0,"(3) Election to have items assigned to each short taxable year under normal tax accounting rules"],[0,"(A) In general"],[2,"A corporation may elect to have paragraph (2) not apply."],[0,"(B) Shareholders must consent to election"],[2,"An election under this subsection shall be valid only if all persons who are shareholders in the corporation at any time during the S short year and all persons who are shareholders in the corporation on the first day of the C short year consent to such election."],[0,"(4) S termination year"],[1,"For purposes of this subsection, the term \"S termination year\" means any taxable year of a corporation (determined without regard to this subsection) in which a termination of an election made under subsection (a) takes effect (other than on the 1st day thereof)."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/1362?type=usc&year=mostrecent&link-type=html"},"by":{"0":"51","1":"29, 29"},"q":[{"src":"brief","b":1,"text":"shareholders holding more than one-half of the shares.","cite":"26 U.S.C. 1362(d)(1)(B)"}]},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"4"}},{"t":"case","label":"Charles E. Clark, Eisner v. Macomber and Some Income Tax Problems","cite":"29 Yale L.J. 735","y":1920,"url":"https://www.courtlistener.com/c/Yale%20L.J./29/735/","by":{"0":"33"}},{"t":"case","label":"Bowers v. Kerbaugh-Empire Co.","cite":"271 U.S. 170","y":1926,"id":"scdb/1925-114","sc":1,"by":{"1":"16, 18"},"q":[{"src":"brief","b":1,"text":"been taken to mean the same thing as used in","cite":"271 U.S. 170, 174"},{"src":"brief","b":1,"text":"In determining what constitutes income[,] substance rather than form is to be given controlling weight.","cite":"271 U.S. at 174"}]},{"t":"case","label":"Bufferd v. Commissioner","cite":"506 U.S. 523","y":1993,"id":"1992/91-7804","sc":1,"by":{"1":"29"}},{"t":"case","label":"Burnet v. Sanford & Brooks Co.","cite":"282 U.S. 359","y":1931,"id":"scdb/1930-115","sc":1,"by":{"1":"13, 35","2":"23, 24"},"q":[{"src":"brief","b":1,"text":"had been in actual operation within the United States before its adoption.","cite":"282 U.S. 359, 365"},{"src":"brief","b":2,"text":"as had been in actual operation within the United States before [the Sixteenth Amendment’s] adoption.","cite":"282 U.S. 359, 365"}]},{"t":"case","label":"Burnet v. Wells","cite":"289 U.S. 670","y":1933,"id":"scdb/1932-094","sc":1,"by":{"1":"44"}},{"t":"case","label":"CFTC v. Schor","cite":"478 U.S. 833","y":1986,"id":"1985/85-621","sc":1,"by":{"1":"29"}},{"t":"case","label":"City of Austin v. Reagan Nat’l Adver. of Austin, LLC","cite":"142 S. Ct. 1464","y":2022,"id":"2021/20-1029","sc":1,"by":{"1":"49"}},{"t":"case","label":"Commissioner v. Obear-Nester Glass Co.","cite":"217 F.2d 56","y":1954,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/217/56/","by":{"1":"39"}},{"t":"case","label":"Cottage Sav. Ass’n v. Commissioner","cite":"499 U.S. 554","y":1991,"id":"1990/89-1965","sc":1,"by":{"1":"32, 39","2":"7"},"q":[{"src":"brief","b":1,"text":"of valuing assets on an annual basis to determine whether the assets ha[ve] appreciated or depreciated in value.","cite":"499 U.S. 554, 559"},{"src":"brief","b":1,"text":"‘the gain or loss from the sale or other disposition of property’ as the difference between ‘the amount realized’ from the sale or disposition of the property and its ‘adjusted basis.’","cite":"499 U.S. at 559"},{"src":"argument","who":"General Prelogar","text":"The Ninth Circuit was referring to this Court's decision in Cottage Savings, where the Court did say that realization requirements are founded on administrative convenience."},{"src":"argument","who":"Mr. Grossman","text":"And so far as Macomber's rule is concerned -- and the Court has applied the dividing line recognized by Macomber as recently as 1975 in Ivan Allen and it's carried forward the same principle in cases like Indianapolis Power & Light in 1990, as well as restating it in Cottage Savings in 1991."}]},{"t":"case","label":"Eder v. Commissioner","cite":"138 F.2d 27","y":1943,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/138/27/","by":{"1":"26"},"q":[{"src":"brief","b":1,"text":"taxpayers’ argument that inability to expend income in the United States, or to use any portion of it in payment of income taxes, necessarily precludes taxability.","cite":"138 F.2d 27, 28"}]},{"t":"case","label":"Estate of Whitlock v. Commissioner: 59 T.C. 490 (1972), aff ’d in relevant part","cite":"494 F.2d 1297","y":1974,"url":"https://www.courtlistener.com/c/F.2d/494/1297/","by":{"1":"27, 46"},"q":[{"src":"brief","b":1,"text":"the history of U.S. income taxation show[ing] that Congress has for decades been drafting income tax statutes which have bypassed the corporate entity","cite":"494 F.2d 1297"}]},{"t":"case","label":"Fernandez v. Wiener","cite":"326 U.S. 340","y":1945,"id":"scdb/1945-022","sc":1,"by":{"1":"47"},"q":[{"src":"brief","b":1,"text":"a particular use or enjoyment of property,","cite":"326 U.S. 340, 352"}]},{"t":"case","label":"Forsyth v. Woods","cite":"78 U.S. 484","y":1870,"id":"scdb/1870-118","sc":1,"by":{"1":"25"}},{"t":"case","label":"Garlock, Inc. v. Commissioner","cite":"489 F.2d 197","y":1973,"court":"2d. Cir.","url":"https://www.courtlistener.com/c/F.2d/489/197/","by":{"1":"26, 27, 40"}},{"t":"case","label":"Helvering v. Clifford","cite":"309 U.S. 331","y":1940,"id":"scdb/1939-115","sc":1,"by":{"1":"12"}},{"t":"case","label":"Helvering v. Estate of Enright","cite":"312 U.S. 636","y":1941,"id":"scdb/1940-102","sc":1,"by":{"1":"30"}},{"t":"case","label":"Helvering v. National Grocery Co.","cite":"304 U.S. 282","y":1938,"id":"scdb/1937-083","sc":1,"by":{"1":"23, 26"}},{"t":"case","label":"Knowlton v. Moore","cite":"178 U.S. 41","y":1900,"id":"scdb/1899-043","sc":1,"by":{"1":"47"},"q":[{"src":"opinion","who":"Justice Thomas, dissenting","text":"the words `uniform throughout the United States' . . . signify . . . a geographical uniformity.","cite":"178 U. S. 41, 106"}]},{"t":"case","label":"Moore v. Harper","cite":"143 S. Ct. 2065","y":2023,"id":"2022/21-1271","sc":1,"by":{"1":"22"},"q":[{"src":"brief","b":1,"text":"long looked to ‘settled and established practice’ to interpret the Constitution.","cite":"143 S. Ct. 2065, 2086"}]},{"t":"case","label":"PPL Corp. v. Commissioner","cite":"569 U.S. 329","y":2013,"id":"2012/12-43","sc":1,"by":{"1":"41, 43"}},{"t":"case","label":"Pollock v. Farmers’ Loan & Trust Co.","cite":"158 U.S. 601","y":1895,"id":"scdb/1894-236","sc":1,"by":{"1":"3, 19, 12, 14","2":"5, 9, 12, 14, 24-26"},"q":[{"src":"brief","b":1,"text":"derived from * * * real or personal property","cite":"158 U.S. 601, 618"},{"src":"brief","b":1,"text":"his proportional share of all profits not then divided.","cite":"158 U.S. at 618"},{"src":"brief","b":2,"text":"bonds, stocks, investments of all kinds,","cite":"158 U.S. 601, 635, 637"},{"src":"opinion","who":"Justice Jackson, concurring","text":"[T]he remedy for such abuses is to be found at the ballot-box, and in a wholesome public opinion which the representatives of the people will not long, if at all, disregard, and not in the disregard by the judiciary of powers that have been committed to another branch of the government.","cite":"158 U. S., at 680"}]},{"t":"case","label":"Seila Law LLC v. CFPB","cite":"140 S. Ct. 2183","y":2020,"id":"2019/19-7","sc":1,"by":{"1":"22"},"q":[{"src":"brief","b":1,"text":"weighty evidence of the Constitution’s meaning.","cite":"140 S. Ct. 2183, 2197"}]},{"t":"case","label":"Spring City Foundry Co. v. Commissioner","cite":"292 U.S. 182","y":1934,"id":"scdb/1933-118","sc":1,"by":{"1":"30"},"q":[{"src":"brief","b":1,"text":"determines the inclusion of the amount in gross income.","cite":"292 U.S. 182, 184"}]},{"t":"case","label":"Springer v. United States","cite":"102 U.S. 586","y":1881,"id":"scdb/1880-080","sc":1,"by":{"1":"3","2":"6"},"q":[{"src":"argument","who":"Mr. Grossman","text":"Well, prior -- I mean, I think the -- the case that addressed this issue prior to Pollock was Springer --"},{"src":"argument","who":"Mr. Grossman","text":"Subsequently, in Brushaber, the Court recognized that at the time, that wasn't really considered or thought about as being much of a defect with respect to the direct tax clauses under sort of the reasoning of Springer."}]},{"t":"case","label":"Stanton v. Baltic Mining Co.","cite":"240 U.S. 103","y":1916,"id":"scdb/1915-080","sc":1,"by":{"1":"4, 14, 18"},"q":[{"src":"brief","b":1,"text":"the previous complete and plenary power of income taxation possessed by Congress from the beginning,","cite":"240 U.S. 103, 112"}]},{"t":"case","label":"State ex rel. Bolens v. Frear","cite":"134 N.W. 673","y":1912,"court":"Wis.","url":"https://www.courtlistener.com/c/N.W./134/673/","by":{"1":"20"}},{"t":"case","label":"Thomas v. United States","cite":"192 U.S. 363","y":1904,"id":"scdb/1903-180","sc":1,"by":{"1":"47","2":"22"}},{"t":"case","label":"Trefry v. Putnam","cite":"116 N.E. 904","y":1917,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E./116/904/","by":{"1":"15, 19","2":"12, 13"},"q":[{"src":"brief","b":1,"text":"[i]ts usual synonyms are ‘gain,’ ‘profit,’ [and] ‘revenue.’","cite":"116 N.E. 904, 908"},{"src":"brief","b":1,"text":"the amount of [property or] wealth which a person has on a fixed date.","cite":"116 N.E. at 907"}]},{"t":"case","label":"United States v. Basye","cite":"410 U.S. 441","y":1973,"id":"1972/71-1022","sc":1,"by":{"1":"29"},"q":[{"src":"brief","b":1,"text":"axiomatic that each partner must pay taxes on his distributive share of the partnership’s income without regard to whether that amount is actually distributed to him.","cite":"410 U.S. 441, 453"},{"src":"opinion","who":"Justice Barrett, concurring in the judgment","text":"each partner must pay taxes on his distributive [i.e., proportional] share of the partnership's income without regard to whether that amount is actually distributed to him.","cite":"410 U. S., at 453"}]},{"t":"case","label":"United States v. Burke","cite":"504 U.S. 229","y":1992,"id":"1991/91-42","sc":1,"by":{"1":"12"},"q":[{"src":"brief","b":1,"text":"the full measure of [Congress’s] taxing power,","cite":"504 U.S. 229, 233"}]},{"t":"case","label":"United States v. Carlton","cite":"512 U.S. 26","y":1994,"id":"1993/92-1941","sc":1,"by":{"1":"43"},"q":[{"src":"brief","b":1,"text":"retroactive tax provision under the Due Process Clause.","cite":"512 U.S. 26, 30"},{"src":"argument","who":"General Prelogar","text":"And I think it's because it clearly fails under precedent, like United States versus Carlton, but, ultimately, I would urge the Court to -- to recognize that that is not about the proper characterization of the underlying tax base."}]},{"t":"case","label":"United States v. Clintwood Elkhorn Mining Co.","cite":"553 U.S. 1","y":2008,"id":"2007/07-308","sc":1,"by":{"1":"49"}},{"t":"case","label":"United States v. Galletti","cite":"541 U.S. 114","y":2004,"id":"2003/02-1389","sc":1,"by":{"1":"25"},"q":[{"src":"brief","b":1,"text":"a partnership maintains a separate identity from its general partners, and the partners are only secondarily liable for the tax debts of the partnership.","cite":"541 U.S. 114, 116"}]},{"t":"case","label":"United States v. Hansen","cite":"143 S. Ct. 1932","y":2023,"id":"2022/22-179","sc":1,"by":{"1":"45"},"q":[{"src":"brief","b":1,"text":"litigants typically lack standing to assert the constitutional rights of third parties,","cite":"143 S. Ct. 1932, 1939"}]},{"t":"case","label":"Walker v. Wait","cite":"50 Vt. 668","y":1878,"url":"https://www.courtlistener.com/c/Vt./50/668/","by":{"1":"25"},"q":[{"src":"brief","b":1,"text":"[a] partnership * * * just as distinct and palpable an entity in the idea of the law, as distinguished from the individuals composing it, as is a corporation.","cite":"50 Vt. 668, 676"}]},{"t":"const","label":"Amendment V","clauses":[["due-process-5","Due Process Clause (Fifth Amendment)"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"1":"7, 44"}},{"t":"const","label":"Amendment XVI, Section 116","clauses":[["sixteenth-amendment","Sixteenth Amendment (Income Tax)"]],"text":"The Congress shall have power to lay and collect taxes on incomes, from whatever source derived, without apportionment among the several States, and without regard to any census or enumeration.","by":{"1":"16"}},{"t":"usc","label":"26 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/26/1","by":{"1":"5"}},{"t":"usc","label":"26 U.S.C. § 11","url":"https://www.law.cornell.edu/uscode/text/26/11","subs":["(b)(1)(2012)"],"by":{"1":"5, 5"}},{"t":"usc","label":"26 U.S.C. § 446","url":"https://www.law.cornell.edu/uscode/text/26/446","subs":["(c)(2)"],"by":{"1":"30"}},{"t":"usc","label":"26 U.S.C. § 448","url":"https://www.law.cornell.edu/uscode/text/26/448","subs":["(a)"],"by":{"1":"30"}},{"t":"usc","label":"26 U.S.C. § 467","url":"https://www.law.cornell.edu/uscode/text/26/467","subs":["(a)"],"by":{"1":"31"}},{"t":"usc","label":"26 U.S.C. § 1259","url":"https://www.law.cornell.edu/uscode/text/26/1259","by":{"1":"31"}},{"t":"usc","label":"26 U.S.C. § 1272","url":"https://www.law.cornell.edu/uscode/text/26/1272","subs":["(a)(1)"],"by":{"1":"31"}},{"t":"usc","label":"26 U.S.C. § 1296","url":"https://www.law.cornell.edu/uscode/text/26/1296","subs":["(a)"],"by":{"1":"31"}},{"t":"usc","label":"26 U.S.C. § 1366","url":"https://www.law.cornell.edu/uscode/text/26/1366","subs":["(a)","(b)"],"by":{"1":"29, 29"}},{"t":"law","label":"Pub. L. No. 87-834","url":"https://www.govinfo.gov/link/statute/76/1006","by":{"1":"4, 26"}},{"t":"law","label":"Tax Cuts and Jobs Act, Pub. L. No. 115-97","url":"https://www.govinfo.gov/link/plaw/115/public/97","by":{"1":"5"}},{"t":"reg","label":"26 C.F.R. § 301.7701-3","url":"https://www.ecfr.gov/current/title-26/section-301.7701-3","subs":["(a)"],"by":{"1":"29"}},{"t":"case","label":"Collector v. Hubbard","cite":"79 U.S. 1","y":1871,"id":"scdb/1870-102","sc":1,"by":{"2":"5, 8, 9, 15"},"q":[{"src":"argument","who":"Justice Alito","text":"I'm sorry to go on so long on this. Your brief makes an awful lot out of Collector versus Hubbard, decided in 1871. To what degree does your argument depend on that?"}]},{"t":"case","label":"Moline Properties, Inc. v. Comm’r","cite":"319 U.S. 436","y":1943,"id":"scdb/1942-081","sc":1,"by":{"2":"19"}},{"t":"case","label":"Nathel v. Comm’r","cite":"615 F.3d 83","y":2010,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/615/83/","by":{"2":"8"}},{"t":"case","label":"Towne v. Eisner","cite":"245 U.S. 418","y":1918,"id":"scdb/1917-208","sc":1,"by":{"2":"3, 18"}},{"t":"case","label":"Yee v. Escondido","cite":"503 U.S. 519","y":1992,"id":"1991/90-1947","sc":1,"by":{"2":"24"}},{"t":"usc","label":"26 U.S.C. § 956","url":"https://www.law.cornell.edu/uscode/text/26/956","by":{"2":"25"}}]};